window.AUTH=window.AUTH||{};window.AUTH["07-636"]={"d":"07-636","id":"2008/07-636","n":"Kennedy v. Plan Administrator for DuPont Sav. and Investment Plan","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae in support of neither party","date":"","url":"https://www.justice.gov/osg/media/200616/dl?inline","side":"us","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/kennedy-v-plan-admr-dupont-sav-and-inv-plan-amicus-merits-0","n":82}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep555/usrep555285/usrep555285.pdf","tr":true,"items":[{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"op":2,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Beck v. Pace Int’l Union","cite":"127 S. Ct. 2310","y":2007,"id":"2006/05-1448","sc":1,"op":1,"sum":"The Court held that \"merger is not a permissible method of terminating a single-employer defined-benefit pension plan.\" Therefore, PACE's argument that Crown was required by ERISA to consider merger as a method of terminating the pension plan was rejected.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Boeing Co. v. United States","cite":"537 U.S. 437","y":2003,"id":"2002/01-1209","sc":1,"sum":"The Court held that section 1.861-8(e)(3) is a proper exercise of the Secretary of the Treasury's rulemaking authority.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Boggs v. Boggs","cite":"520 U.S. 833","y":1997,"id":"1996/96-79","sc":1,"op":10,"sum":"The Court ruled that the Employee Retirement Income Security Act of 1974 (ERISA) preempts state community-property law allowing a non-participant spouse to transfer by a testamentary instrument an interest in undistributed pension plan benefits.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Central Nat’l Bank v. Eells","cite":"215 N.E. 2d 77","y":1965,"court":"Cuyahoga County, Ohio Prob. Ct.","url":"https://www.courtlistener.com/c/N.E.%202d/215/77/","op":1,"by":{"0":"13"}},{"t":"case","label":"Commerce Trust Co. v. Fast","cite":"396 S.W.2d 683","y":1965,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/396/683/","op":1,"by":{"0":"12"}},{"t":"case","label":"Egelhoff v. Egelhoff","cite":"532 U.S. 141","y":2001,"id":"2000/99-1529","sc":1,"op":7,"sum":"The Court held that that the Washington statute has a \"connection with\" ERISA plans and is therefore pre-empted. \"Differing state regulations affecting an ERISA plan's 'system for processing claims and paying benefits' impose 'precisely the burden that ERISA pre-emption was intended to avoid,'\" wrote Justice Thomas.","sumSrc":"Oyez","by":{"0":"24, 26, 28, 30, 31"}},{"t":"case","label":"Estate of Anello v. McQueen","cite":"953 P.2d 1143","y":1998,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/953/1143/","by":{"0":"28"}},{"t":"case","label":"Estate of Altobelli v. IBM","cite":"77 F.3d 78","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/77/78/","op":2,"by":{"0":"27"}},{"t":"case","label":"Estate of Bowden v. Aldridge","cite":"595 A.2d 396","y":1991,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/595/396/","by":{"0":"27"}},{"t":"case","label":"Fox Valley & Vicinity Constr. Workers Pension Fund v. Brown","cite":"897 F.2d 275","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/897/275/","op":3,"by":{"0":"12, 28"}},{"t":"case","label":"Guidry v. Sheet Metal Workers Nat’l Pension Fund","cite":"493 U.S. 365","y":1990,"id":"1989/88-1105","sc":1,"sum":"The constructive trust violates ERISA's prohibition on assignment or alienation of pension benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 18"}},{"t":"case","label":"Harris Trust & Sav. Bank v. Salomon Smith Barney, Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Jewett v. Commissioner","cite":"455 U.S. 305","y":1982,"id":"1981/80-1614","sc":1,"sum":"The \"transfer\" referred to in the Treasury Regulation excepting from the federal gift tax a refusal to accept ownership of an interest in property transferred by will if such refusal is effective under local law and made \"within a reasonable time after knowledge of the existence of the transfer,\" occurs, as indicated by both the text and history of the Regulation, when the interest is created and not at a later time …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Keen v. Weaver","cite":"121 S.W.3d 721","y":2003,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/121/721/","op":3,"by":{"0":"20"}},{"t":"case","label":"Krishna v. Colgate Palmolive Co.","cite":"7 F.3d 11","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/7/11/","op":7,"by":{"0":"27"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Long Island Care at Home, Ltd . v. Coke","cite":"127 S. Ct. 2339","y":2007,"id":"2006/06-593","sc":1,"op":1,"sum":"A unanimous Court ruled that the Department of Labor's regulation was \"valid and binding\" and therefore entitled to all of the deference courts normally give to administrative regulations. The opinion by Justice Stephen Breyer considered the regulation a normal instance of an agency \"filling a statutory gap,\" and rejected each of the lower court's arguments that it was unlawful.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Lyman Lumber Co. v. Hill","cite":"877 F.2d 692","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/877/692/","op":1,"by":{"0":"27"}},{"t":"case","label":"Mackey v. Lanier Collection Agency & Serv., Inc.","cite":"486 U.S. 825","y":1988,"id":"1987/86-1387","sc":1,"sum":"After respondent collection agency obtained money judgments against participants in an \"employee welfare benefit plan\" covered by the Employee Retirement Income Security Act of 1974 (ERISA), its request to garnish the debtors' plan benefits was granted by a Georgia trial court. The State Court of Appeals reversed, holding that Ga. Code Ann. § 18-4-22.1 (1982), barring the garnishment of \"[flunds or benefits of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Manning v. Hayes","cite":"212 F.3d 866","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/212/866/","op":1,"ar":1,"by":{"0":"5"}},{"t":"case","label":"Mertens v. Hewitt Assoc.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"op":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"McGowan v. NJR Serv. Corp.","cite":"423 F.3d 241","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/423/241/","op":1,"by":{"0":"12, 18, 27, 28"}},{"t":"case","label":"McMillan v. Parrott","cite":"913 F.2d 310","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/913/310/","op":1,"by":{"0":"28"}},{"t":"case","label":"Mutual Life Ins. Co. v. Armstrong","cite":"117 U.S. 591","y":1886,"id":"scdb/1885-209","sc":1,"sum":"A policy oí life insurance payable to the assured or his assigns at a future day named, or if he should die before that day to his legal representatives within sixty days after notice and proof of his death, is assignable if the assignment is not made to cover a speculative risk; and an assignment of it passes to the assignee the right to receive the sum insured in case of the death of the assured before the day …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"PaineWebber Inc. v. East","cite":"768 A.2d 1029","y":2001,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/768/1029/","by":{"0":"27"}},{"t":"case","label":"Patterson v. Shumate","cite":"504 U.S. 753","y":1992,"id":"1991/91-913","sc":1,"sum":"The plain language of the Bankruptcy Code and ERISA establishes that an antialienation provision in a qualified pension plan constitutes a restriction on transfer enforceable under \"applicable nonbankruptcy law\" for purposes of § 541(c)(2).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Riggs v. Palmer","cite":"22 N.E. 188","y":1889,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./22/188/","by":{"0":"31"}},{"t":"case","label":"Ridley v. Metropolitan Fed . Bank FSB","cite":"544 N.W.2d 867","y":1996,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/544/867/","sum":"Finding waiver where divorce decree provided that “[e]ach party shall own free of any interest of the other all savings accounts, checking accounts and every other asset of every nature”.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"Roseberry v. Moncure","cite":"429 S.E.2d 4","y":1993,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/429/4/","op":2,"by":{"0":"12"}},{"t":"case","label":"Strong v. Omaha Constr. Indus. Pension Plan","cite":"701 N.W.2d 320","y":2005,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/701/320/","op":1,"by":{"0":"27"}},{"t":"case","label":"Tremaine v. Tremaine","cite":"780 A.2d 522","y":2001,"court":"N.H.","url":"https://www.courtlistener.com/c/A.2d/780/522/","by":{"0":"27"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(2)","(7)","(8)","(13)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1002. Definitions","tname":"Labor","by":{"0":"2, 2, 2, 24, 1"}},{"t":"usc","label":"29 U.S.C. § 1053","url":"https://www.law.cornell.edu/uscode/text/29/1053","subs":["(a)","(a)(3)(A)"],"by":{"0":"13, 13"}},{"t":"usc","label":"29 U.S.C. § 1055","url":"https://www.law.cornell.edu/uscode/text/29/1055","subs":["(a)","(b)(1)(A)","(b)(1)(B)","(b)(1)(C)","(b)(1)(C)(i)","(c)(2)(A)","(c)(2)","(c)(3)"],"stext":{"head":"§1055. Requirement of joint and survivor annuity and preretirement survivor annuity","paras":[[0,"(a) Required contents for applicable plans"],[0,"Each pension plan to which this section applies shall provide that—"],[1,"(1) in the case of a vested participant who does not die before the annuity starting date, the accrued benefit payable to such participant shall be provided in the form of a qualified joint and survivor annuity, and"],[1,"(2) in the case of a vested participant who dies before the annuity starting date and who has a surviving spouse, a qualified preretirement survivor annuity shall be provided to the surviving spouse of such participant."],[0,"(b) Applicable plans"],[0,"(1) This section shall apply to—"],[1,"(A) any defined benefit plan,"],[1,"(B) any individual account plan which is subject to the funding standards of section 1082 of this title, and"],[1,"(C) any participant under any other individual account plan unless—"],[2,"(i) such plan provides that the participant's nonforfeitable accrued benefit (reduced by any security interest held by the plan by reason of a loan outstanding to such participant) is payable in full, on the death of the participant, to the participant's surviving spouse (or, if there is no surviving spouse or the surviving spouse consents in the manner required under subsection (c)(2), to a designated beneficiary),"],[2,"(ii) such participant does not elect the payment of benefits in the form of a life annuity, and"],[2,"(iii) with respect to such participant, such plan is not a direct or indirect transferee (in a transfer after December 31, 1984) of a plan which is described in subparagraph (A) or (B) or to which this clause applied with respect to the participant."],[0,"Clause (iii) of subparagraph (C) shall apply only with respect to the transferred assets (and income therefrom) if the plan separately accounts for such assets and any income therefrom."],[0,"(2)(A) In the case of—"],[1,"(i) a tax credit employee stock ownership plan (as defined in section 409(a) of title 26), or"],[1,"(ii) an employee stock ownership plan (as defined in section 4975(e)(7) of title 26),"],[0,"subsection (a) shall not apply to that portion of the employee's accrued benefit to which the requirements of section 409(h) of title 26 apply."],[0,"(B) Subparagraph (A) shall not apply with respect to any participant unless the requirements of clause 1 (i), (ii), and (iii) of paragraph (1)(C) are met with respect to such participant."],[0,"(4) 2 This section shall not apply to a plan which the Secretary of the Treasury or his delegate has determined is a plan described in section 404(c) of title 26 (or a continuation thereof) in which participation is substantially limited to individuals who, before January 1, 1976, ceased employment covered by the plan."],[0,"(4) 2 A plan shall not be treated as failing to meet the requirements of paragraph (1)(C) or (2) merely because the plan provides that benefits will not be payable to the surviving spouse of the participant unless the participant and such spouse had been married throughout the 1-year period ending on the earlier of the participant's annuity starting date or the date of the participant's death."],[0,"(c) Plans meeting requirements of section"],[0,"(1) A plan meets the requirements of this section only if—"],[1,"(A) under the plan, each participant—"],[2,"(i) may elect at any time during the applicable election period to waive the qualified joint and survivor annuity form of benefit or the qualified preretirement survivor annuity form of benefit (or both),"],[2,"(ii) if the participant elects a waiver under clause (i), may elect the qualified optional survivor annuity at any time during the applicable election period, and"],[2,"(iii) may revoke any such election at any time during the applicable election period, and"],[1,"(B) the plan meets the requirements of paragraphs (2), (3), and (4)."],[0,"(2) Each plan shall provide that an election under paragraph (1)(A)(i) shall not take effect unless—"],[1,"(A)(i) the spouse of the participant consents in writing to such election, (ii) such election designates a beneficiary (or a form of benefits) which may not be changed without spousal consent (or the consent of the spouse expressly permits designations by the participant without any requirement of further consent by the spouse), and (iii) the spouse's consent acknowledges the effect of such election and is witnessed by a plan representative or a notary public, or"],[1,"(B) it is established to the satisfaction of a plan representative that the consent required under subparagraph (A) may not be obtained because there is no spouse, because the spouse cannot be located, or because of such other circumstances as the Secretary of the Treasury may by regulations prescribe."],[0,"Any consent by a spouse (or establishment that the consent of a spouse may not be obtained) under the preceding sentence shall be effective only with respect to such spouse."],[0,"(3)(A) Each plan shall provide to each participant, within a reasonable period of time before the annuity starting date (and consistent with such regulations as the Secretary of the Treasury may prescribe) a written explanation of—"],[1,"(i) the terms and conditions of the qualified joint and survivor annuity and of the qualified optional survivor annuity,"],[1,"(ii) the participant's right to make, and the effect of, an election under paragraph (1) to waive the joint and survivor annuity form of benefit,"],[1,"(iii) the rights of the participant's spouse under paragraph (2), and"],[1,"(iv) the right to make, and the effect of, a revocation of an election under paragraph (1)."],[0,"(B)(i) Each plan shall provide to each participant, within the applicable period with respect to such participant (and consistent with such regulations as the Secretary may prescribe), a written explanation with respect to the qualified preretirement survivor annuity comparable to that required under subparagraph (A)."],[0,"(ii) For purposes of clause (i), the term \"applicable period\" means, with respect to a participant, whichever of the following periods ends last:"],[1,"(I) The period beginning with the first day of the plan year in which the participant attains age 32 and ending with the close of the plan year preceding the plan year in which the participant attains age 35."],[1,"(II) A reasonable period after the individual becomes a participant."],[1,"(III) A reasonable period ending after paragraph (5) ceases to apply to the participant."],[1,"(IV) A reasonable period ending after this section applies to the participant."],[0,"In the case of a participant who separates from service before attaining age 35, the applicable period shall be a reasonable period after separation."],[0,"(4) Each plan shall provide that, if this section applies to a participant when part or all of the participant's accrued benefit is to be used as security for a loan, no portion of the participant's accrued benefit may be used as security for such loan unless—"],[1,"(A) the spouse of the participant (if any) consents in writing to such use during the 90-day period ending on the date on which the loan is to be so secured, and"],[1,"(B) requirements comparable to the requirements of paragraph (2) are met with respect to such consent."],[0,"(5)(A) The requirements of this subsection shall not apply with respect to the qualified joint and survivor annuity form of benefit or the qualified preretirement survivor annuity form of benefit, as the case may be, if such benefit may not be waived (or another beneficiary selected) and if the plan fully subsidizes the costs of such benefit."],[0,"(B) For purposes of subparagraph (A), a plan fully subsidizes the costs of a benefit if under the plan the failure to waive such benefit by a participant would not result in a decrease in any plan benefits with respect to such participant and would not result in increased contributions from such participant."],[0,"(6) If a plan fiduciary acts in accordance with part 4 of this subtitle in—"],[1,"(A) relying on a consent or revocation referred to in paragraph (1)(A), or"],[1,"(B) making a determination under paragraph (2),"],[0,"then such consent, revocation, or determination shall be treated as valid for purposes of discharging the plan from liability to the extent of payments made pursuant to such Act."],[0,"(7) For purposes of this subsection, the term \"applicable election period\" means—"],[1,"(A) in the case of an election to waive the qualified joint and survivor annuity form of benefit, the 180-day period ending on the annuity starting date, or"],[1,"(B) in the case of an election to waive the qualified preretirement survivor annuity, the period which begins on the first day of the plan year in which the participant attains age 35 and ends on the date of the participant's death."],[0,"In the case of a participant who is separated from service, the applicable election period under subparagraph (B) with respect to benefits accrued before the date of such separation from service shall not begin later than such date."],[0,"(8) Notwithstanding any other provision of this subsection—"],[1,"(A)(i) A plan may provide the written explanation described in paragraph (3)(A) after the annuity starting date. In any case to which this subparagraph applies, the applicable election period under paragraph (7) shall not end before the 30th day after the date on which such explanation is provided."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1055?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§1055. Requirement of joint and survivor annuity and preretirement survivor annuity","tname":"Labor","by":{"0":"16, 29, 14, 14, 14, 15, 15, 15, 15, 15"}},{"t":"usc","label":"29 U.S.C. § 1056","url":"https://www.law.cornell.edu/uscode/text/29/1056","subs":["(d)(1)","(d)(2)","(d)(3)","(d)(3)(A)","(d)(3)(B)","(d)(3)(B)(i)","(d)(3)(B)(i)(I)","(d)(3)(B)(ii)","(d)(3)(C)","(d)(3)(D)","(d)(3)(G)","(d)(3)(J)","(d)(3)(K)","(d)(3)(N)","(d)(4)"],"stext":{"head":"§1056. Form and payment of benefits","paras":[[0,"(a) Commencement date for payment of benefits"],[0,"Each pension plan shall provide that unless the participant otherwise elects, the payment of benefits under the plan to the participant shall begin not later than the 60th day after the latest of the close of the plan year in which—"],[1,"(1) occurs the date on which the participant attains the earlier of age 65 or the normal retirement age specified under the plan,"],[1,"(2) occurs the 10th anniversary of the year in which the participant commenced participation in the plan, or"],[1,"(3) the participant terminates his service with the employer."],[0,"In the case of a plan which provides for the payment of an early retirement benefit, such plan shall provide that a participant who satisfied the service requirements for such early retirement benefit, but separated from the service (with any nonforfeitable right to an accrued benefit) before satisfying the age requirement for such early retirement benefit, is entitled upon satisfaction of such age requirement to receive a benefit not less than the benefit to which he would be entitled at the normal retirement age, actuarially reduced under regulations prescribed by the Secretary of the Treasury."],[0,"(b) Decrease in plan benefits by reason of increases in benefit levels under Social Security Act or Railroad Retirement Act of 1937"],[0,"If—"],[1,"(1) a participant or beneficiary is receiving benefits under a pension plan, or"],[1,"(2) a participant is separated from the service and has non-forfeitable rights to benefits,"],[0,"a plan may not decrease benefits of such a participant by reason of any increase in the benefit levels payable under title II of the Social Security Act [42 U.S.C. 401 et seq.] or the Railroad Retirement Act of 1937 [45 U.S.C. 231 et seq.] or any increase in the wage base under such title II, if such increase takes place after September 2, 1974, or (if later) the earlier of the date of first entitlement of such benefits or the date of such separation."],[0,"(c) Forfeiture of accrued benefits derived from employer contributions"],[0,"No pension plan may provide that any part of a participant's accrued benefit derived from employer contributions (whether or not otherwise nonforfeitable) is forfeitable solely because of withdrawal by such participant of any amount attributable to the benefit derived from contributions made by such participant. The preceding sentence shall not apply (1) to the accrued benefit of any participant unless, at the time of such withdrawal, such participant has a nonforfeitable right to at least 50 percent of such accrued benefit, or (2) to the extent that an accrued benefit is permitted to be forfeited in accordance with section 1053(a)(3)(D)(iii) of this title."],[0,"(d) Assignment or alienation of plan benefits"],[0,"(1) Each pension plan shall provide that benefits provided under the plan may not be assigned or alienated."],[0,"(2) For the purposes of paragraph (1) of this subsection, there shall not be taken into account any voluntary and revocable assignment of not to exceed 10 percent of any benefit payment, or of any irrevocable assignment or alienation of benefits executed before September 2, 1974. The preceding sentence shall not apply to any assignment or alienation made for the purposes of defraying plan administration costs. For purposes of this paragraph a loan made to a participant or beneficiary shall not be treated as an assignment or alienation if such loan is secured by the participant's accrued non-forfeitable benefit and is exempt from the tax imposed by section 4975 of title 26 (relating to tax on prohibited transactions) by reason of section 4975(d)(1) of title 26."],[0,"(3)(A) Paragraph (1) shall apply to the creation, assignment, or recognition of a right to any benefit payable with respect to a participant pursuant to a domestic relations order, except that paragraph (1) shall not apply if the order is determined to be a qualified domestic relations order. Each pension plan shall provide for the payment of benefits in accordance with the applicable requirements of any qualified domestic relations order."],[0,"(B) For purposes of this paragraph—"],[1,"(i) the term \"qualified domestic relations order\" means a domestic relations order—"],[2,"(I) which creates or recognizes the existence of an alternate payee's right to, or assigns to an alternate payee the right to, receive all or a portion of the benefits payable with respect to a participant under a plan, and"],[2,"(II) with respect to which the requirements of subparagraphs (C) and (D) are met, and"],[1,"(ii) the term \"domestic relations order\" means any judgment, decree, or order (including approval of a property settlement agreement) which—"],[2,"(I) relates to the provision of child support, alimony payments, or marital property rights to a spouse, former spouse, child, or other dependent of a participant, and"],[2,"(II) is made pursuant to a State or Tribal domestic relations law (including a community property law)."],[1,"For purposes of clause (ii)(II), the term \"Tribal\" with respect to a domestic relations law means such a law which is issued by or under the laws of an Indian tribal government (as defined in section 7701(a)(40) of title 26), a subdivision of such an Indian tribal government, or an agency or instrumentality of either."],[0,"(C) A domestic relations order meets the requirements of this subparagraph only if such order clearly specifies—"],[1,"(i) the name and the last known mailing address (if any) of the participant and the name and mailing address of each alternate payee covered by the order,"],[1,"(ii) the amount or percentage of the participant's benefits to be paid by the plan to each such alternate payee, or the manner in which such amount or percentage is to be determined,"],[1,"(iii) the number of payments or period to which such order applies, and"],[1,"(iv) each plan to which such order applies."],[0,"(D) A domestic relations order meets the requirements of this subparagraph only if such order—"],[1,"(i) does not require a plan to provide any type or form of benefit, or any option, not otherwise provided under the plan,"],[1,"(ii) does not require the plan to provide increased benefits (determined on the basis of actuarial value), and"],[1,"(iii) does not require the payment of benefits to an alternate payee which are required to be paid to another alternate payee under another order previously determined to be a qualified domestic relations order."],[0,"(E)(i) A domestic relations order shall not be treated as failing to meet the requirements of clause (i) of subparagraph (D) solely because such order requires that payment of benefits be made to an alternate payee—"],[1,"(I) in the case of any payment before a participant has separated from service, on or after the date on which the participant attains (or would have attained) the earliest retirement age,"],[1,"(II) as if the participant had retired on the date on which such payment is to begin under such order (but taking into account only the present value of benefits actually accrued and not taking into account the present value of any employer subsidy for early retirement), and"],[1,"(III) in any form in which such benefits may be paid under the plan to the participant (other than in the form of a joint and survivor annuity with respect to the alternate payee and his or her subsequent spouse)."],[0,"For purposes of subclause (II), the interest rate assumption used in determining the present value shall be the interest rate specified in the plan or, if no rate is specified, 5 percent."],[0,"(ii) For purposes of this subparagraph, the term \"earliest retirement age\" means the earlier of—"],[1,"(I) the date on which the participant is entitled to a distribution under the plan, or"],[1,"(II) the later of the date of 1 the participant attains age 50 or the earliest date on which the participant could begin receiving benefits under the plan if the participant separated from service."],[0,"(F) To the extent provided in any qualified domestic relations order—"],[1,"(i) the former spouse of a participant shall be treated as a surviving spouse of such participant for purposes of section 1055 of this title (and any spouse of the participant shall not be treated as a spouse of the participant for such purposes), and"],[1,"(ii) if married for at least 1 year, the surviving former spouse shall be treated as meeting the requirements of section 1055(f) of this title."],[0,"(G)(i) In the case of any domestic relations order received by a plan—"],[1,"(I) the plan administrator shall promptly notify the participant and each alternate payee of the receipt of such order and the plan's procedures for determining the qualified status of domestic relations orders, and"],[1,"(II) within a reasonable period after receipt of such order, the plan administrator shall determine whether such order is a qualified domestic relations order and notify the participant and each alternate payee of such determination."],[0,"(ii) Each plan shall establish reasonable procedures to determine the qualified status of domestic relations orders and to administer distributions under such qualified orders. Such procedures—"],[1,"(I) shall be in writing,"],[1,"(II) shall provide for the notification of each person specified in a domestic relations order as entitled to payment of benefits under the plan (at the address included in the domestic relations order) of such procedures promptly upon receipt by the plan of the domestic relations order, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1056?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§1056. Form and payment of benefits","tname":"Labor","by":{"0":"3, 7, 8, 21, 1, 16, 3, 11, 21, 8, 3, 13, 22, 3, 21, 26, 26, 3, 26, 3, 16, 21, 26, 3, 16, 22, 2, 21"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)","(b)(4)"],"stext":{"head":"§1102. Establishment of plan","paras":[[0,"(a) Named fiduciaries"],[0,"(1) Every employee benefit plan shall be established and maintained pursuant to a written instrument. Such instrument shall provide for one or more named fiduciaries who jointly or severally shall have authority to control and manage the operation and administration of the plan."],[0,"(2) For purposes of this subchapter, the term \"named fiduciary\" means a fiduciary who is named in the plan instrument, or who, pursuant to a procedure specified in the plan, is identified as a fiduciary (A) by a person who is an employer or employee organization with respect to the plan or (B) by such an employer and such an employee organization acting jointly."],[0,"(b) Requisite features of plan"],[0,"Every employee benefit plan shall—"],[1,"(1) provide a procedure for establishing and carrying out a funding policy and method consistent with the objectives of the plan and the requirements of this subchapter,"],[1,"(2) describe any procedure under the plan for the allocation of responsibilities for the operation and administration of the plan (including any procedure described in section 1105(c)(1) of this title),"],[1,"(3) provide a procedure for amending such plan, and for identifying the persons who have authority to amend the plan, and"],[1,"(4) specify the basis on which payments are made to and from the plan."],[0,"(c) Optional features of plan"],[0,"Any employee benefit plan may provide—"],[1,"(1) that any person or group of persons may serve in more than one fiduciary capacity with respect to the plan (including service both as trustee and administrator);"],[1,"(2) that a named fiduciary, or a fiduciary designated by a named fiduciary pursuant to a plan procedure described in section 1105(c)(1) of this title, may employ one or more persons to render advice with regard to any responsibility such fiduciary has under the plan; or"],[1,"(3) that a person who is a named fiduciary with respect to control or management of the assets of the plan may appoint an investment manager or managers to manage (including the power to acquire and dispose of) any assets of a plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1102?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1102. Establishment of plan","tname":"Labor","by":{"0":"2, 2, 9, 23"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)(A)","(a)(1)(D)"],"by":{"0":"2, 2, 9, 23"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(1)(B)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"5"}},{"t":"usc","label":"29 U.S.C. § 1135","url":"https://www.law.cornell.edu/uscode/text/29/1135","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 1136","url":"https://www.law.cornell.edu/uscode/text/29/1136","subs":["(b)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)","(b)(2)(A)","(b)(7)"],"by":{"0":"30, 30, 21"}},{"t":"usc","label":"26 U.S.C. § 7805","url":"https://www.law.cornell.edu/uscode/text/26/7805","by":{"0":"18, 18"}},{"t":"law","label":"Pub. L. No. 98-397","url":"https://www.govinfo.gov/link/statute/98/1426","by":{"0":"14"}},{"t":"law","label":"Pub. L. No. 94-455","url":"https://www.govinfo.gov/link/statute/90/1893","by":{"0":"17"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(a)(9)","(a)(13)"],"stext":{"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","paras":[[0,"(a) Requirements for qualification"],[0,"A trust created or organized in the United States and forming part of a stock bonus, pension, or profit-sharing plan of an employer for the exclusive benefit of his employees or their beneficiaries shall constitute a qualified trust under this section—"],[1,"(1) if contributions are made to the trust by such employer, or employees, or both, or by another employer who is entitled to deduct his contributions under section 404(a)(3)(B) (relating to deduction for contributions to profit-sharing and stock bonus plans), or by a charitable remainder trust pursuant to a qualified gratuitous transfer (as defined in section 664(g)(1)), for the purpose of distributing to such employees or their beneficiaries the corpus and income of the fund accumulated by the trust in accordance with such plan;"],[1,"(2) if under the trust instrument it is impossible, at any time prior to the satisfaction of all liabilities with respect to employees and their beneficiaries under the trust, for any part of the corpus or income to be (within the taxable year or thereafter) used for, or diverted to, purposes other than for the exclusive benefit of his employees or their beneficiaries (but this paragraph shall not be construed, in the case of a multiemployer plan, to prohibit the return of a contribution within 6 months after the plan administrator determines that the contribution was made by a mistake of fact or law (other than a mistake relating to whether the plan is described in section 401(a) or the trust which is part of such plan is exempt from taxation under section 501(a), or the return of any withdrawal liability payment determined to be an overpayment within 6 months of such determination));"],[1,"(3) if the plan of which such trust is a part satisfies the requirements of section 410 (relating to minimum participation standards); and"],[1,"(4) if the contributions or benefits provided under the plan do not discriminate in favor of highly compensated employees (within the meaning of section 414(q)). For purposes of this paragraph, there shall be excluded from consideration employees described in section 410(b)(3)(A) and (C)."],[1,"(5) Special rules relating to nondiscrimination requirements.—"],[2,"(A) Salaried or clerical employees.—A classification shall not be considered discriminatory within the meaning of paragraph (4) or section 410(b)(2)(A)(i) merely because it is limited to salaried or clerical employees."],[2,"(B) Contributions and benefits may bear uniform relationship to compensation.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan bear a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees."],[2,"(C) Certain disparity permitted.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan favor highly compensated employees (as defined in section 414(q)) in the manner permitted under subsection (l)."],[2,"(D) Integrated defined benefit plan.—"],[3,"(i) In general.—A defined benefit plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the plan provides that the employer-derived accrued retirement benefit for any participant under the plan may not exceed the excess (if any) of—"],[4,"(I) the participant's final pay with the employer, over"],[4,"(II) the employer-derived retirement benefit created under Federal law attributable to service by the participant with the employer."],[0,"For purposes of this clause, the employer-derived retirement benefit created under Federal law shall be treated as accruing ratably over 35 years."],[3,"(ii) Final pay.—For purposes of this subparagraph, the participant's final pay is the compensation (as defined in section 414(q)(4)) paid to the participant by the employer for any year—"],[4,"(I) which ends during the 5-year period ending with the year in which the participant separated from service for the employer, and"],[4,"(II) for which the participant's total compensation from the employer was highest."],[2,"(E) 2 or more plans treated as single plan.—For purposes of determining whether 2 or more plans of an employer satisfy the requirements of paragraph (4) when considered as a single plan—"],[3,"(i) Contributions.—If the amount of contributions on behalf of the employees allowed as a deduction under section 404 for the taxable year with respect to such plans, taken together, bears a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees, the plans shall not be considered discriminatory merely because the rights of employees to, or derived from, the employer contributions under the separate plans do not become nonforfeitable at the same rate."],[3,"(ii) Benefits.—If the employees' rights to benefits under the separate plans do not become nonforfeitable at the same rate, but the levels of benefits provided by the separate plans satisfy the requirements of regulations prescribed by the Secretary to take account of the differences in such rates, the plans shall not be considered discriminatory merely because of the difference in such rates."],[2,"(F) Social security retirement age.—For purposes of testing for discrimination under paragraph (4)—"],[3,"(i) the social security retirement age (as defined in section 415(b)(8)) shall be treated as a uniform retirement age, and"],[3,"(ii) subsidized early retirement benefits and joint and survivor annuities shall not be treated as being unavailable to employees on the same terms merely because such benefits or annuities are based in whole or in part on an employee's social security retirement age (as so defined)."],[2,"(G) Governmental plans.—Paragraphs (3) and (4) shall not apply to a governmental plan (within the meaning of section 414(d))."],[1,"(6) A plan shall be considered as meeting the requirements of paragraph (3) during the whole of any taxable year of the plan if on one day in each quarter it satisfied such requirements."],[1,"(7) A trust shall not constitute a qualified trust under this section unless the plan of which such trust is a part satisfies the requirements of section 411 (relating to minimum vesting standards)."],[1,"(8) A trust forming part of a defined benefit plan shall not constitute a qualified trust under this section unless the plan provides that forfeitures must not be applied to increase the benefits any employee would otherwise receive under the plan."],[1,"(9) Required distributions.—"],[2,"(A) In general.—A trust shall not constitute a qualified trust under this subsection unless the plan provides that the entire interest of each employee—"],[3,"(i) will be distributed to such employee not later than the required beginning date, or"],[3,"(ii) will be distributed, beginning not later than the required beginning date, in accordance with regulations, over the life of such employee or over the lives of such employee and a designated beneficiary (or over a period not extending beyond the life expectancy of such employee or the life expectancy of such employee and a designated beneficiary)."],[2,"(B) Required distribution where employee dies before entire interest is distributed.—"],[3,"(i) Where distributions have begun under subparagraph (A)(ii).—A trust shall not constitute a qualified trust under this section unless the plan provides that if—"],[4,"(I) the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), and"],[4,"(II) the employee dies before his entire interest has been distributed to him,"],[0,"the remaining portion of such interest will be distributed at least as rapidly as under the method of distributions being used under subparagraph (A)(ii) as of the date of his death."],[3,"(ii) 5-year rule for other cases.—A trust shall not constitute a qualified trust under this section unless the plan provides that, if an employee dies before the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), the entire interest of the employee will be distributed within 5 years after the death of such employee."],[3,"(iii) Exception to 5-year rule for certain amounts payable over life of beneficiary.—If—"],[4,"(I) any portion of the employee's interest is payable to (or for the benefit of) a designated beneficiary,"],[4,"(II) such portion will be distributed (in accordance with regulations) over the life of such designated beneficiary (or over a period not extending beyond the life expectancy of such beneficiary), and"],[4,"(III) such distributions begin not later than 1 year after the date of the employee's death or such later date as the Secretary may by regulations prescribe,"],[0,"for purposes of clause (ii), the portion referred to in subclause (I) shall be treated as distributed on the date on which such distributions begin."],[3,"(iv) Special rule for surviving spouse of employee.—If the designated beneficiary referred to in clause (iii)(I) is the surviving spouse of the employee and the surviving spouse elects the treatment in this clause—"],[4,"(I) the regulations referred to in clause (iii)(II) shall treat the surviving spouse as if the surviving spouse were the employee,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","tname":"Internal Revenue Code","by":{"0":"19, 17, 21"}},{"t":"usc","label":"26 U.S.C. § 2518","url":"https://www.law.cornell.edu/uscode/text/26/2518","subs":["(b)"],"stext":{"head":"§2518. Disclaimers","paras":[[0,"(a) General rule"],[0,"For purposes of this subtitle, if a person makes a qualified disclaimer with respect to any interest in property, this subtitle shall apply with respect to such interest as if the interest had never been transferred to such person."],[0,"(b) Qualified disclaimer defined"],[0,"For purposes of subsection (a), the term \"qualified disclaimer\" means an irrevocable and unqualified refusal by a person to accept an interest in property but only if—"],[1,"(1) such refusal is in writing,"],[1,"(2) such writing is received by the transferor of the interest, his legal representative, or the holder of the legal title to the property to which the interest relates not later than the date which is 9 months after the later of—"],[2,"(A) the day on which the transfer creating the interest in such person is made, or"],[2,"(B) the day on which such person attains age 21,"],[1,"(3) such person has not accepted the interest or any of its benefits, and"],[1,"(4) as a result of such refusal, the interest passes without any direction on the part of the person making the disclaimer and passes either—"],[2,"(A) to the spouse of the decedent, or"],[2,"(B) to a person other than the person making the disclaimer."],[0,"(c) Other rules"],[0,"For purposes of subsection (a)—"],[0,"(1) Disclaimer of undivided portion of interest"],[1,"A disclaimer with respect to an undivided portion of an interest which meets the requirements of the preceding sentence shall be treated as a qualified disclaimer of such portion of the interest."],[0,"(2) Powers"],[1,"A power with respect to property shall be treated as an interest in such property."],[0,"(3) Certain transfers treated as disclaimers"],[1,"A written transfer of the transferor's entire interest in the property—"],[2,"(A) which meets requirements similar to the requirements of paragraphs (2) and (3) of subsection (b), and"],[2,"(B) which is to a person or persons who would have received the property had the transferor made a qualified disclaimer (within the meaning of subsection (b)),"],[1,"shall be treated as a qualified disclaimer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/2518?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§2518. Disclaimers","tname":"Internal Revenue Code","by":{"0":"17, 19, 17"}},{"t":"reg","label":"3 C.F.R. pt. 332","url":"https://www.ecfr.gov/current/title-3/part-332","by":{"0":"2"}}]};